use vstd::prelude::*;

verus! {

fn ones(n: usize) -> (result: Vec<i8>)
    ensures
        result.len() == n,
        // every element is exactly 1
        forall|i: int| 0 <= i < n ==> result[i] == 1i8,
        // any two in-bounds indices have equal elements (constant vector)
        forall|i: int, j: int|
            0 <= i < n && 0 <= j < n ==> result[i] == result[j],
        // every element is strictly positive
        forall|i: int| 0 <= i < n ==> result[i] > 0i8,
{
    let mut v: Vec<i8> = Vec::new();

    let mut idx: usize = 0;
    while idx < n
        invariant
            v.len() == idx,
            idx <= n,
            // built prefix is all ones
            forall|i: int| 0 <= i < idx ==> v[i] == 1i8,
            // built prefix is constant
            forall|i: int, j: int|
                0 <= i < idx && 0 <= j < idx ==> v[i] == v[j],
            // built prefix is strictly positive
            forall|i: int| 0 <= i < idx ==> v[i] > 0i8,
        decreases n - idx,
    {
        v.push(1i8);
        idx = idx + 1;
    }

    // At this point, idx == n and v.len() == n, and the invariants give the postconditions.
    v
}

} // verus!

